25	#include <dirent.h>
26	#include <errno.h>
27	#include <fcntl.h>
28	#include <stdio.h>    /* renameat: POSIX puts it here, next to rename */
29	#include <stdlib.h>
30	#include <string.h>
31	#include <unistd.h>
32	
33	/* The ctx: the log directory, open for as long as storage is. */
34	typedef struct {
35	    int dir_fd;
36	} linux_dir;
37	
38	/* 1 if `name` is a plain file name inside the directory: not NULL, not
39	 * empty, short enough for a row, no '/', and not "." or "..". Anything
40	 * else could reach outside the directory. */
41	static int name_ok(const char *name)
42	{
43	    return name != NULL && name[0] != '\0' && strlen(name) < GT_FILE_NAME_MAX
44	           && strchr(name, '/') == NULL && strcmp(name, ".") != 0 && strcmp(name, "..") != 0;
45	}
46	
47	static gt_status file_open(void *ctx, const char *name, unsigned flags, int *handle_out)
48	{
49	    linux_dir *dir = ctx;
50	    if (!name_ok(name) || handle_out == NULL) {
51	        return GT_ERR_INVAL;
52	    }
53	    int open_flags = O_RDWR | O_CLOEXEC | ((flags & GT_FILE_CREATE) ? O_CREAT : 0);
54	    int fd;
55	    /* Repeat only while a signal interrupted the call. */
56	    do {
57	        fd = openat(dir->dir_fd, name, open_flags, 0644);
58	    } while (fd < 0 && errno == EINTR);
59	    if (fd < 0) {
60	        return GT_ERR_IO;
61	    }
62	    *handle_out = fd;
63	    return GT_OK;
64	}

1	/* The 8 B seq_resume reply, storage -> hub (see storage_proto.h).
2	 *
3	 * Purpose: turns a gt_resume into the exact bytes storage sends a newly
4	 * connected hub, and back, so the hub can carry on numbering after the
5	 * last seq storage holds. As in log_record.c and ipc_msg.c, fields are
6	 * written one byte at a time, little-endian, never by copying the struct.
7	 *
8	 * Pure byte packing: no sockets. */
9	#include "storage_proto.h"
10	
11	#include <stddef.h>
12	
13	gt_status gt_resume_encode(const gt_resume *resume, uint8_t out[GT_RESUME_SIZE])
14	{
15	    if (resume == NULL || out == NULL) {
16	        return GT_ERR_INVAL;
17	    }
18	    uint32_t seq = resume->has_last ? resume->seq : 0;   /* no seq without has_last */
19	
20	    out[0] = GT_RESUME_MAGIC;
21	    out[1] = GT_RESUME_VERSION;
22	    out[2] = GT_RESUME_TYPE;
23	    out[3] = resume->has_last ? 1 : 0;
24	    out[4] = (uint8_t)(seq);
25	    out[5] = (uint8_t)(seq >> 8);
26	    out[6] = (uint8_t)(seq >> 16);
27	    out[7] = (uint8_t)(seq >> 24);
28	    return GT_OK;
29	}
30	
31	/* Every check runs before `resume` is written, so a rejected reply leaves
32	 * it exactly as it was. Each byte is widened to uint32_t before shifting,
33	 * so a shift by 24 can't overflow an int. */
34	gt_status gt_resume_decode(const uint8_t in[GT_RESUME_SIZE], gt_resume *resume)
35	{
36	    if (in == NULL || resume == NULL) {
37	        return GT_ERR_INVAL;
38	    }
39	    uint32_t seq = (uint32_t)in[4] | ((uint32_t)in[5] << 8)
40	                 | ((uint32_t)in[6] << 16) | ((uint32_t)in[7] << 24);
41	    if (in[0] != GT_RESUME_MAGIC || in[1] != GT_RESUME_VERSION || in[2] != GT_RESUME_TYPE
42	        || in[3] > 1 || (in[3] == 0 && seq != 0)) {
43	        return GT_ERR_CORRUPT;
44	    }
45	    resume->has_last = in[3];
46	    resume->seq = seq;
47	    return GT_OK;
48	}
49	
50	/* after_reply is the first seq storage doesn't hold yet. The UINT32_MAX
51	 * check comes before the + 1, so it can never wrap around to 0. */
52	gt_status gt_next_seq(int has_own, uint32_t own_next, const gt_resume *resume,
53	                      uint32_t *next_out)
54	{
55	    if (resume == NULL || next_out == NULL) {
56	        return GT_ERR_INVAL;
57	    }
58	    if (resume->has_last && resume->seq == UINT32_MAX) {
59	        return GT_ERR_FULL;
60	    }
61	    uint32_t after_reply = resume->has_last ? resume->seq + 1 : 0;
62	    *next_out = (has_own && own_next > after_reply) ? own_next : after_reply;
63	    return GT_OK;
64	}
