129	/* Accept a waiting hub. FD_CLOEXEC is set by hand because accept4() (which
130	 * could set it in one call) is not POSIX. A newer hub replaces the
131	 * current one. Returns the connection to use from now on (-1 if none). */
132	static int accept_hub(gt_storage *storage, int listen_fd, int conn_fd, gt_storage_log_fn log,
133	                      void *log_ctx)
134	{
135	    int new_fd = accept(listen_fd, NULL, NULL);
136	    if (new_fd < 0) {
137	        return conn_fd;   /* nothing to accept after all; keep the current hub */
138	    }
139	    fcntl(new_fd, F_SETFD, FD_CLOEXEC);
140	    if (conn_fd >= 0) {
141	        close(conn_fd);
142	        log(log_ctx, GT_LOG_WARN, "hub_duplicate_client", NULL);
143	    }
144	    if (!send_resume(storage, new_fd, log, log_ctx)) {
145	        return drop_hub(new_fd, log, log_ctx);
146	    }
147	    return new_fd;
148	}
149	
150	/* Stopping: take every frame the hub already sent, so nothing waiting in
151	 * the socket is lost. Returns the connection afterwards (-1 if the hub
152	 * closed it or sent a bad frame). */
153	static int drain_on_stop(gt_storage *storage, int conn_fd, gt_storage_log_fn log,
154	                         void *log_ctx)
155	{
156	    /* invariant: every frame read so far has been handed to storage */
157	    while (conn_fd >= 0) {
158	        frame_result result = read_frame(storage, conn_fd, log, log_ctx);
159	        if (result == FRAME_NONE) {
160	            break;
161	        }
162	        if (result == FRAME_CLOSE) {
163	            conn_fd = drop_hub(conn_fd, log, log_ctx);
164	        }
165	    }
166	    return conn_fd;
167	}
