169	gt_status gt_storage_serve(gt_storage *storage, int listen_fd, int stop_fd,
170	                           gt_storage_log_fn log, void *log_ctx)
171	{
172	    if (storage == NULL || log == NULL || listen_fd < 0 || stop_fd < 0) {
173	        return GT_ERR_INVAL;
174	    }
175	    int conn_fd = -1;
176	    gt_status status = GT_OK;
177	
178	    for (;;) {
179	        /* poll() skips an entry whose fd is negative, so "no hub" is -1. */
180	        struct pollfd waits[3] = {
181	            { .fd = listen_fd, .events = POLLIN, .revents = 0 },
182	            { .fd = stop_fd,   .events = POLLIN, .revents = 0 },
183	            { .fd = conn_fd,   .events = POLLIN, .revents = 0 },
184	        };
185	        if (poll(waits, 3, -1) < 0) {
186	            if (errno == EINTR) {
187	                continue;
188	            }
189	            status = GT_ERR_IO;
190	            break;
191	        }
192	
193	        /* Frames before connects, as in hub_listen: a new entry's revents
194	         * is never read in the round it was added. */
195	        if (conn_fd >= 0 && (waits[2].revents & (POLLIN | POLLHUP | POLLERR))
196	            && read_frame(storage, conn_fd, log, log_ctx) == FRAME_CLOSE) {
197	            conn_fd = drop_hub(conn_fd, log, log_ctx);
198	        }
199	        if (waits[0].revents & POLLIN) {
200	            conn_fd = accept_hub(storage, listen_fd, conn_fd, log, log_ctx);
201	        }
202	        if (waits[1].revents & POLLIN) {
203	            conn_fd = drain_on_stop(storage, conn_fd, log, log_ctx);
204	            break;
205	        }
206	    }
207	    if (conn_fd >= 0) {
208	        close(conn_fd);
209	    }
210	    return status;
211	}
